insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-22466')::uuid, md5('building-ueberseering-12-22297')::uuid, '22466', 'ein-moderner-klassiker-das-komplex-revitalisierte-arne-jacobsen-haus-in-der-city-nord-22466', 'Ein moderner Klassiker - das komplex revitalisierte Arne Jacobsen Haus in der City Nord.', 'Der 1969 eingeweihte, futuristische Bürokomplex am Überseering wurde von dem dänischen Architekten Arne Jacobsen entworfen und gehört wohl zu den markantesten Gebäuden der City …', 'Der 1969 eingeweihte, futuristische Bürokomplex am Überseering wurde von dem dänischen Architekten Arne Jacobsen entworfen und gehört wohl zu den markantesten Gebäuden der City Nord. Es wird ab Frühjahr 2024 umfangreich aber behutsam in Zusammenarbeit mit dem Denkmalschutzamt revitalisiert. Die U-Bahn-Station Sengelmannstraße und die S-Bahn-Station Rübenkamp sichern neben verschiedenen Buslinien eine gute Anbindung an den öffentlichen Nahverkehr. Die Mietflächen werden in Absprache mit den Mietern hochwertig und nachhaltig mit Be- und Entlüftungsanlagen, LED-Leuchtkonzepten mit Präsenzschaltung, Sonnen- und Blendschutz, Küchenzeilen und separaten WC-Einheiten ausgestattet. Im Erdgeschoss auf der Nordseite wird eine Konferenzebene eingerichtet und auf der Südseite ist ein Coworking- und Bistrobereich für alle Mieter geplant. Das Highlight des Bürokomplexes wird eine, für alle Mieter zugängliche, Dachterrasse sein. PKW Stellplätze können direkt am Haus angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse', 'barrierefrei', 'stellplaetze']::text[], 1890, 12300, 'https://www.buerohamburg.de/objects/pdf/BHI_22466.pdf', null, 'filemaker', '22466') on conflict (id) do nothing;
